/**
 * Targeted insert of ingredient_i18n rows for one or more languages — never
 * a full reseed, which would re-read/re-write every existing row (10 langs *
 * ~1039 ingredients) for no reason. Reads names straight from
 * pipeline/out/ingredients.jsonl (regenerated by 03_normalize_ingredients.mjs,
 * a purely local step — the OFF taxonomy already carries pt/it/bn/ru/pnb/jv
 * name data, no pipeline code change was needed to pick it up once those
 * codes were added to pipeline/lib/langs.mjs's SUPPORTED_LANGS).
 *
 * canonical_key -> ingredient_id needs one real mapping, cached locally
 * (pipeline/out/ingredient_ids.json) after the first run so repeat runs for
 * other languages cost zero extra reads.
 *
 * Every ingredient-name query in src/ already does
 * COALESCE(t.name, en.name, i.canonical_key) with a LEFT JOIN — a missing
 * row for a given (ingredient_id, lang) falls back to English, never blank.
 * Confirmed by reading match.ts / +page.server.ts / api/ingredients before
 * writing this script, precisely so partial per-language coverage is safe
 * to load incrementally.
 *
 * Usage:
 *   node pipeline/tools/load_ingredient_i18n.mjs --lang=pt,it,bn,ru,pnb,jv [--dry-run] [--local]
 */

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import { esc, d1 } from '../lib/d1.mjs';

const OUT_DIR = path.resolve('pipeline/out');
const INGREDIENTS_PATH = path.join(OUT_DIR, 'ingredients.jsonl');
const IDS_CACHE_PATH = path.join(OUT_DIR, 'ingredient_ids.json');
const FLUSH_EVERY = 100; // names are a few bytes each, not multi-KB instructions — safe to batch wider

function parseArgs() {
	const args = process.argv.slice(2);
	const str = (flag) => {
		const hit = args.find((a) => a.startsWith(`--${flag}=`));
		return hit ? hit.split('=').slice(1).join('=') : undefined;
	};
	const langs = (str('lang') ?? '').split(',').filter(Boolean);
	if (!langs.length) throw new Error('--lang=<comma-separated codes> is required');
	return { langs, dryRun: args.includes('--dry-run'), local: args.includes('--local') };
}

function loadIngredientRows() {
	if (!existsSync(INGREDIENTS_PATH)) {
		throw new Error(`${INGREDIENTS_PATH} not found — run node pipeline/03_normalize_ingredients.mjs first.`);
	}
	return readFileSync(INGREDIENTS_PATH, 'utf8')
		.trim()
		.split('\n')
		.map((line) => JSON.parse(line));
}

function loadIdMap(local) {
	if (existsSync(IDS_CACHE_PATH)) {
		return new Map(Object.entries(JSON.parse(readFileSync(IDS_CACHE_PATH, 'utf8'))));
	}
	const rows = d1('SELECT id, canonical_key FROM ingredients', { local });
	const map = new Map(rows.map((r) => [r.canonical_key, r.id]));
	writeFileSync(IDS_CACHE_PATH, JSON.stringify(Object.fromEntries(map)) + '\n');
	return map;
}

function main() {
	const { langs, dryRun, local } = parseArgs();
	const ingredientRows = loadIngredientRows();
	const idByKey = loadIdMap(local);

	for (const lang of langs) {
		const inserts = [];
		let missing = 0;
		let noId = 0;
		for (const row of ingredientRows) {
			const name = row.names[lang];
			if (!name) {
				missing++;
				continue;
			}
			const id = idByKey.get(row.canonical_key);
			if (!id) {
				noId++; // taxonomy/manual key not seeded into `ingredients` yet — shouldn't happen, but don't silently insert garbage
				continue;
			}
			inserts.push({ id, name });
		}

		console.log(
			`load_ingredient_i18n: ${lang} — ${inserts.length} names to insert, ${missing} missing from taxonomy/manual, ${noId} keys with no matching ingredient id`
		);

		if (dryRun) continue;

		for (let i = 0; i < inserts.length; i += FLUSH_EVERY) {
			const chunk = inserts.slice(i, i + FLUSH_EVERY);
			const values = chunk.map((r) => `(${r.id},${esc(lang)},${esc(r.name)})`).join(',\n');
			d1(
				`INSERT OR IGNORE INTO ingredient_i18n (ingredient_id, lang, name) VALUES\n${values};`,
				{ local, json: false }
			);
		}
		console.log(`load_ingredient_i18n: ${lang} — inserted ${inserts.length} rows`);
	}
}

main();
